import JSON
import SpecialFunctions: erfcx

"""
	gen( domain, name )

Generate fixture data and write to file.

The scaled complementary error function is evaluated in extended precision, as `Float64` implementations form `x^2` before exponentiating it.

# Arguments

* `domain`: domain
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = range( -26.0, stop = -1.0, length = 2001 );
julia> gen( x, "data.json" );
```
"""
function gen( domain, name )
	x = collect( domain );
	y = setprecision( BigFloat, 256 ) do
		Float64.( erfcx.( BigFloat.( x ) ) );
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("expected", y)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Medium negative values (previously generated with SciPy, whose `erfcx` forms `x^2` in double precision as well):
x = range( -10.0, stop = -1.0, length = 1707 );
gen( x, "medium_negative.json" );

# Negative values, down to where the function overflows:
x = range( -26.6, stop = -1.0, length = 2001 );
gen( x, "negative.json" );
